import re

# ===== أيقونات =====
icon_client   = ""    # قطع يسار
icon_assistant = ""    # قطع يمين

def fix_dashboard(path, icon_b64, label):
    print(f"\n{'='*40}")
    print(f"🔧 {label}")
    print(f"{'='*40}")
    
    with open(path, "r", encoding="utf-8") as f:
        html = f.read()
    
    changes = 0
    
    def rep(old, new):
        nonlocal changes, html
        c = html.count(old)
        if c:
            html = html.replace(old, new)
            changes += c
            print(f"  ✅ غيّر: {old[:40]} ({c}x)")
        else:
            print(f"  ⚪ مش موجود: {old[:40]}")
    
    # 1. body background = أصفر (الـ gradient)
    rep('#5C4A00 0%,#7A6200 50%,#5C4A00 100%', '#FFE600 0%,#E6CA00 50%,#FFE600 100%')
    rep('#1B5E20 0%,#2E7D32 50%,#1B5E20 100%', '#FFE600 0%,#E6CA00 50%,#FFE600 100%')
    
    # 2. theme-color = أصفر
    rep('content="#5C4A00"', 'content="#FFE600"')
    rep('content="#1B5E20"', 'content="#FFE600"')
    rep('content="#2E7D32"', 'content="#FFE600"')
    
    # 3. CSS variables = navy (للكروت)
    rep('--dark:#5C4A00;', '--dark:#0D1B4B;')
    rep('--dark2:#7A6200;', '--dark2:#1E2761;')
    rep('--dark:#1B5E20;', '--dark:#0D1B4B;')
    rep('--dark2:#2E7D32;', '--dark2:#1E2761;')
    
    # 4. header background = navy
    rep('background:rgba(92,74,0,0.85)',   'background:rgba(13,27,75,0.95)')
    rep('background:rgba(92,74,0,0.95)',   'background:rgba(13,27,75,0.95)')
    rep('background:rgba(27,94,32,0.85)',  'background:rgba(13,27,75,0.95)')
    rep('background:rgba(27,94,32,0.95)',  'background:rgba(13,27,75,0.95)')
    rep('background:rgba(46,125,50,0.85)', 'background:rgba(13,27,75,0.95)')
    rep('background:rgba(46,125,50,0.95)', 'background:rgba(13,27,75,0.95)')
    
    # 5. modal background = navy
    rep('background:#7A6200;', 'background:#1E2761;')
    rep('background:#1B5E20;', 'background:#1E2761;')
    rep('background:#2E7D32;', 'background:#1E2761;')
    
    # 6. أي لون قديم متبقي
    rep('#5C4A00', '#0D1B4B')
    rep('#7A6200', '#1E2761')
    rep('#1B5E20', '#0D1B4B')
    rep('#2E7D32', '#1E2761')
    
    # 7. الأيقونة
    old_count = len(re.findall(r'data:image/png;base64,[A-Za-z0-9+/=]+', html))
    html = re.sub(r'data:image/png;base64,[A-Za-z0-9+/=]+', f'data:image/png;base64,{icon_b64}', html)
    print(f"  ✅ أيقونات: {old_count}")
    
    with open(path, "w", encoding="utf-8") as f:
        f.write(html)
    
    print(f"  ✅ تم الحفظ! ({changes} تغيير)")

# تشغيل على الملفين
fix_dashboard(
    r"C:\Users\karim\Documents\GitHub\amin-alsir-test\amin_alsir_client_dashboard.html",
    icon_client,
    "داشبورد العميل (قطع يسار)"
)

fix_dashboard(
    r"C:\Users\karim\Documents\GitHub\amin-alsir-test\amin_alsir_assistant_dashboard.html",
    icon_assistant,
    "داشبورد المساعد (قطع يمين)"
)

print("\n\n🎉 انتهى! الملفين جاهزين للـ push")
